fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new(); // Handle empty array case
    }

    // Calculate the effective offset to avoid unnecessary full rotations
    let effective_offset = offset % n;

    // Create a new vector for the result
    let mut result = Vec::with_capacity(n);

    // Fill the result vector with the rotated values
    for i in 0..n {
        let new_index = (i + effective_offset) % n;
        result.push(a[new_index]);
    }

    result
}